(* [comment removed for export] *)
Definition TTE_STACK : Z := 64 + AASSIGN_STACK.

Definition tte_W (lo : Z) (sp : word) (T E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (T, T + 8); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z.

Definition tte_post_r (r : tte_res) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (tte_ret r P (P + Z.of_nat (length bs)))) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (tte_W lo sp T E) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ bytes_at asegs m' P bs
    /\ rw_cells asegs m' T (tte_tl r P tj)
    /\ rw_cells asegs m' E (ErrCodeCells (tte_ec r E0))
    /\ AHttpCat m' (tte_cat r g) /\ AXStatics m'
    /\ ACONST m' /\ stack0 m' lo shi.                                  (* [comment removed for export] *)

Definition tte_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj : list byte) (m : mem) : machine_state -> Prop :=
  tte_post_r (tte_class bs) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo shi bs E0 g tj m.

Definition tte_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj : list byte),
  bytes_at asegs m P bs ->
  rw_cells asegs m T [CB 8 tj] ->
  rw_cells asegs m E (ErrCodeCells E0) -> ec_ok E0 ->
  AHttpCat m g -> AXStatics m ->
  stk asegs m lo (bv_unsigned sp) -> lo + TTE_STACK <= bv_unsigned sp -> aceil <= lo ->          (* [comment removed for export] *)
  aapp P (Z.of_nat (length bs)) -> P + Z.of_nat (length bs) <= lo ->                           (* [comment removed for export] *)
  bv_unsigned sp <= T -> T + 8 <= shi -> T mod 8 = 0 ->                                         (* [comment removed for export] *)
  aapp E 24 -> E mod 8 = 0 -> (P + Z.of_nat (length bs) <= E \/ E + 24 <= P) ->                 (* [comment removed for export] *)
  mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 ->
  ACONST m -> stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  accessible m P (Z.of_nat (length bs)) -> accessible m E 24 -> shvis m E (E + 24) ->
  evt asegs (tte_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo shi bs E0 g tj m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (P + Z.of_nat (length bs))) (wz T) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BP_PARSE_TOKEN_TO_EOL) fc None m (seg_rom asegs)).

