(* [comment removed for export] *)
Definition tte_ctx (m m1 : mem) (sp s0v s1v s2v s3v rav : word) (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool)
    (tj junk : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -64) [CB 24 junk]
  /\ rw_cells asegs m1 (bv_unsigned sp + -40) [C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 T [CB 8 tj]
  /\ rw_cells asegs m1 E (ErrCodeCells E0)
  /\ stk asegs m1 lo (bv_unsigned sp + -64)
  /\ bytes_at asegs m1 P bs
  /\ munch (tte_W lo sp T E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ tte_side m1 P E lo shi (Z.of_nat (length bs)) g.

(* [comment removed for export] *)
Definition tte_pure (sp : word) (P T E lo shi : Z) (bs : list byte) (E0 : ecv) : Prop :=
  ec_ok E0 /\ lo + TTE_STACK <= bv_unsigned sp /\ aceil <= lo /\ aapp P (Z.of_nat (length bs)) /\ P + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= T /\ T + 8 <= shi /\ T mod 8 = 0 /\ aapp E 24 /\ E mod 8 = 0
  /\ (P + Z.of_nat (length bs) <= E \/ E + 24 <= P) /\ bv_unsigned sp mod 16 = 0 /\ bv_unsigned sp + 64 <= shi.

Local Ltac open_ctx CTX PURE :=
  destruct CTX as (FRlo & FRhi & TL & EC & ST & WIN & MU & WM & MI & SIDE);
  destruct PURE as (EOK & LO & CEIL & APP & PHI & TLO & THI & TAL & APE & EAL & PE & SPAL & SHI);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof (stack0_bounds _ _ _ (proj1 (proj2 SIDE))) as [SKB1 SKB2];
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  unfold ErrCodeCells in EC;
  unfold tte_W, TTE_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *.

Local Ltac join_frameA LOW HIGH base :=
  lazymatch type of LOW with rw_cells _ ?mx _ ?cs1 =>
  lazymatch type of HIGH with rw_cells _ _ ?ah ?cs2 =>
    let J := fresh "FRJ" in
    assert (J : rw_cells asegs mx base (cs1 ++ cs2))
      by (apply (proj2 (rw_cells_app asegs mx base cs1 cs2)); split; [exact LOW | cbn [cells_size csize Nat.add];
            lazymatch goal with |- rw_cells _ _ ?a _ => replace a with ah by lia end; exact HIGH]);
    clear LOW HIGH; cbn [app] in J; rename J into LOW
  end end.

Local Ltac split_frameA FR cs1 cs2 LOW HIGH :=
  lazymatch type of FR with rw_cells _ ?mx ?base _ =>
    apply (proj1 (rw_cells_app asegs mx base cs1 cs2)) in FR;
    destruct FR as [LOW HIGH]; cbn [cells_size csize Nat.add] in HIGH;
    repeat match type of HIGH with
