(* [comment removed for export] *)
Lemma tte_exit_ctl : forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s0x s0v s1v s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj junk : list byte),
  tte_ctx m m1 sp s0v s1v s2v s3v ra P T E lo shi bs E0 g tj junk -> tte_pure sp P T E lo shi bs E0 ->
  evt asegs (tte_post_r TTE_ctl ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo shi bs E0 g tj m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0x (wz E) a0 a1 a2 a3 a4 a5 a6 a7
              (wz ASHADOW_BASE) s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
