Scheme kc__6 := Elimination for Corelib.Init.Datatypes.option Sort Prop.

(* [comment removed for export] *)
Lemma tte_found : forall rax ra sp gp tp t0 t1 t2 a3 a4 s1v s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P T E lo shi : Z) (bs : list byte) (E0 : ecv) (g : bool) (tj junk : list byte)
    (i : nat) (cb : byte) (s0v : word),
  tte_ctx m m1 sp s0v s1v s2v s3v ra P T E lo shi bs E0 g tj junk -> tte_pure sp P T E lo shi bs E0 ->
  find_ix is_ctl bs = Some i -> nth_error bs i = Some cb -> zb cb < 32 -> zb cb <> 9 ->
  evt asegs (tte_post ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc P T E lo shi bs E0 g tj m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz (P + Z.of_nat (length bs))) (wz E)
              (wz (P + Z.of_nat i)) (wz (P + Z.of_nat i + 1)) (wz T) a3 a4 (wz 127) (wz 9) (wz (zb cb))
              (wz ASHADOW_BASE) s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
